const hash=url=>crypto.createHash('sha256').update(fs.readFileSync(url)).digest('hex'),beforeHash=hash(moduleURL);
const E=await import(moduleURL),{createGame:engineCreateGame,choose,validGame,overall,club,projectProfile,participation,observedPromise,marketEvidence,CLUBS,POSITIONS}=E;
