const createGame=(name,position,seed)=>engineCreateGame(name,position,seed,{challenge:false});
const clone=x=>JSON.parse(JSON.stringify(x)),pick=(g,k)=>g.event.choices.find(c=>c.id.split('@')[0]===k),byId=id=>CLUBS.find(c=>c.id===id);
