const check=(name,fn)=>{try{fn();groups.push({name,pass:true});console.log('PASS',name);}catch(e){groups.push({name,pass:false,error:e.stack});console.error('FAIL',name,e.stack);}};
function policy(g,{routine='REST',formation=0,rival='challenge',style=0,move='prospect',tier='D'}={}){const k=g.event.kind;return k==='FORMATION'?g.event.choices[formation]:k==='ENTRY'?g.event.choices.find(c=>c.profile.division===tier)??g.event.choices[0]:k==='RIVALRY'?pick(g,'rival:'+rival):k==='ROUTINE'?pick(g,'routine:'+routine):k==='PLAN'?g.event.choices[style]:k==='RECOVERY'?pick(g,'recovery:READ'):k==='DECISIVE'?pick(g,'decisive:safe'):k==='INTEREST'&&move==='prospect'?g.event.choices.find(c=>c.profile?.recruitment==='PROSPECT')??pick(g,'market:stay'):['CONTACT','OFFER'].includes(k)&&move==='prospect'?g.event.choices[0]:pick(g,'market:stay')??g.event.choices[0];}
function advance(g,kind,opts={}){let n=0;while(g.phase!=='DONE'&&g.event.kind!==kind){assert(choose(g,policy(g,opts).id),g.event.kind);assert(++n<180);}assert.equal(g.event.kind,kind);return g;}
function finish(g,opts={},observer=()=>{}){let n=0;while(g.phase!=='DONE'){assert(validGame(g),g.event.kind);observer(g);const loaded=clone(g),c=policy(g,opts);assert(c,g.event.kind);assert(choose(g,c.id));assert(choose(loaded,c.id));assert.deepEqual(g,loaded);assert(++n<180);}assert(validGame(g));assert.equal(g.age,25);assert.equal(g.playedMatches.length,126);assert.equal(g.yearStats.length,7);assert.equal(g.objectiveHistory.length,21);return g;}
function offer(position,seed){const g=createGame('Promessa pública '+position,position,seed);let n=0;while(g.phase!=='DONE'&&g.season<=21){if(g.event.kind==='OFFER'&&g.offer.profile.recruitment==='PROSPECT')return g;assert(choose(g,policy(g).id));assert(++n<180);}throw Error('natural PROSPECT OFFER absent '+position+seed);}
function planFromOffer(source){const g=clone(source);assert(choose(g,g.event.choices[0].id));return advance(g,'PLAN',{move:'stay'});}
function healthy(g){g.condition=100;g.fatigue=0;g.happiness=100;g.mentalStress=0;g.pressure=30;g.confidence=60;g.trust=48;g.rival.form=6.7;g.fanMemory[g.clubId].respect=50;assert(validGame(g));return g;}
function opportunity(g,kind=g.clubProject?.recruitment??'READY'){return participation(g,g.clubId,g.rival.quality,g.rival.form??6.7,kind);}
const publicOffers={};
check('public07 pending effects replay exactly before prospective08 adoption and DONE25 stays closed',()=>{assert.equal(frozen.engineSha256,'224926279cc2a6f80f2b2dd2ffb2ffc55f46d7565f6ca581f4133ecb1f9defa2');const rows=[];for(const[k,snapshot]of Object.entries(frozen.snapshots)){const g=clone(snapshot),raw=JSON.stringify(g);assert(validGame(g),k);assert.equal(JSON.stringify(g),raw);if(k==='DONE'){assert.equal(choose(g,'forged@'+g.serial),false);assert.equal(E.extendCareer(g),null);assert.equal(JSON.stringify(g),raw);continue;}const expected=frozen.effects[k];assert(choose(g,expected.id),k);if(k==='ENDPLAN'){for(const field of ['skills','dna','condition','fatigue','happiness','mentalStress','confidence','trust','pressure','playedMatches','lastMatches','totalstats','seasonStats','progression','objectiveHistory','choicesLog','yearStats','clubProject','salary','rival'])assert.deepEqual(g[field],expected.after[field],k+' past effect '+field);assert.equal(g.promiseRevision,1);assert.equal(g.event.kind,'INTEREST');}else if(k==='PLAN'){const beforeNext=x=>{const y=clone(x);delete y.event;delete y.objective;delete y.challengeRevision;if(expected.after.event.kind==='RECOVERY')for(const field of ['recoveryUsed','recoveryArc','recoveryLast'])delete y[field];return y;};assert.deepEqual(beforeNext(g),beforeNext(expected.after),k+' consumed pending effects changed');if(expected.after.event.kind==='RECOVERY')for(const field of ['recoveryUsed','recoveryArc','recoveryLast'])assert.deepEqual(g[field],snapshot[field],k+' rewrote existing recovery facts');assert.equal(g.challengeRevision,1);assert.equal(g.event.kind,'PLAN');assert.equal(g.objective.revision,2);}else assert.deepEqual(g,expected.after,k+' pending replay changed');const before=clone(snapshot);finish(g,{move:'stay'});for(const field of ['playedMatches','objectiveHistory','progression','choicesLog','history','yearStats'])assert.deepEqual(g[field].slice(0,before[field].length),before[field],k+' rewrote '+field);assert.equal(g.promiseRevision,1);rows.push({kind:k,preservedMatches:before.playedMatches.length,finalMatches:g.playedMatches.length});}metrics.compatibility=rows;});
check('natural ST and GK acquired careers can jump directly D to A as observed PROSPECT projects',()=>{for(const[position,seed]of [['ST',1],['GK',3]]){const g=offer(position,seed);assert(validGame(g));assert.equal(club(g).division,'D');assert.equal(g.offer.profile.division,'A');assert.equal(g.offer.profile.recruitment,'PROSPECT');assert(observedPromise(g).eligible);assert(g.age>=18&&g.age<=20);assert.equal(g.history.length,1);const dna=clone(g.dna),skills=clone(g.skills),contract=clone(g.offer.profile);publicOffers[position]=clone(g);const replay=createGame(g.name,g.position,g.seed);for(const c of g.choicesLog)assert(choose(replay,c.id));assert.deepEqual(replay,g);assert(choose(g,g.event.choices[0].id));assert.deepEqual(g.skills,skills);assert.deepEqual(g.dna,dna);assert.deepEqual(g.history.map(h=>byId(h.clubId).division),['D','A']);assert(g.age<=21);assert.equal(g.salary,contract.monthly);assert.equal(g.clubProject.recruitment,'PROSPECT');assert.equal(g.clubProject.trainingQuality,contract.trainingQuality);assert.match(contract.role,/Promessa/);assert(contract.starterChance<.25);metrics[position+'Natural']={seed,source:g.history[0].clubId,to:g.clubId,offerAge:g.age-1,signedAge:g.age,ovr:overall(g),forecast:contract.minutesEstimate,chance:contract.starterChance,choiceIds:publicOffers[position].choicesLog.map(c=>c.id)};}});
check('young already-ready ordinary recruitment preserves07 forecasts and nominal minutes exactly',()=>{const old=clone(frozen.snapshots.READY_OFFER),target=old.offer.profile.clubId,p=clone(old.offer.profile);assert(overall(old)>=p.rivalQuality-3);old.promiseRevision=1;assert(validGame(old));const current=projectProfile(old,target);assert.equal(current.recruitment,'READY');const stripped=clone(current);delete stripped.recruitment;assert.deepEqual(stripped,p);const state={...old,trust:48,pressure:p.pressure},model=participation(state,target,p.rivalQuality,6.7,'READY');assert.equal(model.integration,1);assert.equal(model.substituteChance,.74);assert.equal(model.substituteMin,14);assert.equal(model.substituteMax,34);assert.equal(model.starterChance,p.starterChance);assert.deepEqual(model.minutesEstimate,p.minutesEstimate);metrics.ready={seed:old.seed,target,age:old.age,ovr:overall(old),rival:p.rivalQuality,chance:p.starterChance,forecast:p.minutesEstimate};});
check('public candidate cohorts keep silent and failed windows; adults poor evidence and hiddenDNA cannot manufacture promise',()=>{let windows=0,silent=0,prospectContacts=0,failures=0,adult=0,poor=0;for(const {id:position}of POSITIONS)for(let seed=1;seed<=16;seed++){const g=createGame('Coorte promessa',position,seed);let n=0;while(g.phase!=='DONE'&&g.season<=22){if(g.event.kind==='INTEREST'){windows++;silent+=+!g.market.length;assert(g.market.length<=2);const observed=observedPromise(g);assert.deepEqual(observedPromise({...g,dna:{learning:0,aptitudes:{}}}),observed,'recruitment reads hiddenDNA');if(g.age>=22){adult++;assert.equal(observed.eligible,false);}for(const id of g.market){const p=g.event.choices.find(c=>c.id.split('@')[0]==='contact:'+id).profile;if(p.recruitment==='PROSPECT'){prospectContacts++;assert(observed.eligible);assert.equal(p.division,'A');assert(g.age<=21);assert(p.rivalQuality-overall(g)>=8);}}}if(g.event.kind==='ASSESSMENT_RESULT')failures++;assert(choose(g,policy(g).id));assert(++n<180);}const low=createGame('Coorte sem evidência',position,seed);advance(low,'INTEREST',{routine:'TRAIN',style:2,move:'stay'});if(!observedPromise(low).eligible){poor++;assert(low.market.every(id=>low.marketContexts[id].recruitment!=='PROSPECT'));}}assert(silent>0&&failures>0&&prospectContacts>0&&adult>0&&poor>0);metrics.candidates={careers:128,windows,silent,prospectContacts,failedNegotiations:failures,adultWindows:adult,poorExcluded:poor};});
check('shared profiles equal consumed first-match probabilities and paired PROSPECT cohorts have little initial participation',()=>{const rows={};for(const position of ['ST','GK']){const base=healthy(planFromOffer(publicOffers[position])),model=opportunity(base),profile=projectProfile(base,base.clubId);assert.equal(profile.starterChance,model.starterChance);assert.deepEqual(profile.minutesEstimate,model.minutesEstimate);const expectedMean=model.starterChance*(model.starterMin+model.starterMax)/2+(1-model.starterChance)*model.substituteChance*(model.substituteMin+model.substituteMax)/2;assert.equal(model.mean,expectedMean);const totals={PROSPECT:{starts:0,minutes:0,bench:0,cameos:0},READY:{starts:0,minutes:0,bench:0,cameos:0}};for(let seed=1;seed<=128;seed++)for(const recruitment of ['PROSPECT','READY']){const g=clone(base);g.clubProject.recruitment=recruitment;g.rng=(Math.imul(seed,2654435761)+17)>>>0;assert(validGame(g));const live=projectProfile(g,g.clubId),before=opportunity(g);assert.equal(live.starterChance,before.starterChance);assert(choose(g,g.event.choices[0].id));assert.equal(g.lastMatches[0].starterChance,before.starterChance,'actual first selection diverges from shared forecast');const m=g.lastMatches[0];if(!m.started&&m.minutes){assert(m.minutes>=before.substituteMin&&m.minutes<=before.substituteMax);if(position==='GK')assert.equal(m.keeperMinutesReason,'CONTINGENCY');}for(const x of g.lastMatches){totals[recruitment].starts+=+x.started;totals[recruitment].minutes+=x.minutes;totals[recruitment].bench+=+!x.minutes;totals[recruitment].cameos+=+!!(x.minutes&&!x.started);if(position==='GK')assert.equal(x.goals,0);}}assert(totals.PROSPECT.minutes<totals.READY.minutes);assert(totals.PROSPECT.starts<128*6*.15);assert(totals.PROSPECT.bench>128*6*.5);rows[position]={pairs:128,forecastMean:model.mean,forecast:profile.minutesEstimate,model,totals};}metrics.participation=rows;});
check('development and qualified club evidence improve integration while readiness releases it without an age or DNA cap',()=>{const rows=[];let naturalImprovement=0;for(const position of ['ST','GK']){const g=planFromOffer(publicOffers[position]),initial=opportunity(g).integration;let peak=initial;finish(g,{move:'stay'},x=>{if(x.event.kind==='PLAN')peak=Math.max(peak,opportunity(x).integration);});naturalImprovement+=+!!(peak>initial);const high=clone(g);for(const k of Object.keys(high.skills))high.skills[k]=95;high.proficiency=95;high.condition=100;high.fatigue=0;high.happiness=100;high.mentalStress=0;high.pressure=30;assert(validGame(high));const matured=opportunity(high,'PROSPECT'),ready=opportunity(high,'READY');assert.equal(matured.integration,1);assert.deepEqual(matured,ready);assert.deepEqual(opportunity({...high,age:18,dna:{learning:0,aptitudes:{}}}),matured,'integration has age/DNA ceiling');const live=projectProfile(high,high.clubId);assert(!/Promessa · banco/.test(live.role));rows.push({position,initialIntegration:initial,peakNaturalIntegration:peak,finalNaturalOverall:overall(g),readinessRelease:matured.integration});}assert(naturalImprovement>0,'no acquired trajectory improves integration');const developing=planFromOffer(offer('ST',28)),initial=opportunity(developing).integration;let peak=initial;finish(developing,{move:'stay'},x=>{if(x.event.kind==='PLAN')peak=Math.max(peak,opportunity(x).integration);});assert(peak>initial);assert.equal(developing.history[1].clubId,'sao-paulo');rows.push({position:'ST',seed:28,signedAge:22,initialIntegration:initial,peakNaturalIntegration:peak,finalNaturalOverall:overall(developing),projectMinutes:developing.playedMatches.filter(m=>m.clubId==='sao-paulo').reduce((n,m)=>n+m.minutes,0)});metrics.development=rows;});
check('new promise market and frozen profile markers reject malformed and cross-state forgeries atomically',()=>{const source=publicOffers.ST,mutations=[g=>g.promiseRevision=2,g=>g.promiseRevision='1',g=>delete g.promiseRevision,g=>g.marketRevision=2,g=>g.marketRevision='1',g=>g.offer.profile.recruitment='AUTOMATIC',g=>g.offer.profile.recruitment='PROSPECT_BAD',g=>g.marketContexts[g.contactClub].recruitment='NO',g=>g.marketContexts[g.contactClub].recruitment='READY',g=>delete g.marketContexts[g.contactClub].recruitment,g=>g.offer.profile.division='B',g=>g.offer.profile.monthly=NaN];for(const mutate of mutations){const g=clone(source);mutate(g);const raw=JSON.stringify(g);assert.equal(validGame(g),false);assert.doesNotThrow(()=>assert.equal(choose(g,g.event.choices[0].id),false));assert.equal(JSON.stringify(g),raw);}const entry=advance(createGame('Guard entry','ST',1),'ENTRY');entry.entryOffers[2].recruitment='PROSPECT';entry.event.choices[2].profile=clone(entry.entryOffers[2]);assert.equal(validGame(entry),false);const interest=clone(frozen.snapshots.INTEREST);interest.promiseRevision=1;interest.marketRevision=1;for(const id of interest.market)interest.marketContexts[id].recruitment='READY';for(const c of interest.event.choices)if(c.profile)c.profile.recruitment='READY';assert(validGame(interest));const badInterest=clone(interest);badInterest.event.choices[0].profile.recruitment='PROSPECT';const rawInterest=JSON.stringify(badInterest);assert.equal(validGame(badInterest),false);assert.equal(choose(badInterest,badInterest.event.choices[0].id),false);assert.equal(JSON.stringify(badInterest),rawInterest);const naturalInterest=createGame(source.name,source.position,source.seed);for(const c of source.choicesLog.slice(0,-2))assert(choose(naturalInterest,c.id));assert.equal(naturalInterest.event.kind,'INTEREST');const prospectId=naturalInterest.market.find(id=>naturalInterest.marketContexts[id].recruitment==='PROSPECT');assert(prospectId);for(const mode of ['READY','REMOVE']){const forged=clone(naturalInterest);if(mode==='READY')forged.marketContexts[prospectId].recruitment='READY';else delete forged.marketContexts[prospectId].recruitment;const raw=JSON.stringify(forged);assert.equal(validGame(forged),false);assert.equal(choose(forged,forged.event.choices[0].id),false);assert.equal(JSON.stringify(forged),raw);}metrics.atomicRejections=mutations.length+4;});
check('qualified historical production increases market evidence at identical ability without reading future objectives',()=>{
 const fresh=createGame('Amostra pública','AM',1),empty=marketEvidence(fresh);assert.equal(empty.bonus,0);assert.equal(empty.confidence,0);
 const pairs=[],totals={scanned:128,excludedByHistoricalInput:0,pairs:0,postBonusHigher:0,strongContacts:0,ordinaryStrongContacts:0,contacts:0,ordinaryContacts:0,silent:0,ordinarySilent:0,bonusSum:0,ordinaryBonusSum:0,postOverallDifferenceSum:0};
 function history(position,seed,style){const g=createGame('Produção pública',position,seed);let n=0;while(!(g.event.kind==='PLAN'&&g.period===2)){assert(choose(g,policy(g,{tier:'B',style,move:'stay'}).id));assert(++n<60);}return g;}
 for(const position of ['AM','ST'])for(let seed=1;seed<=64;seed++){
  const a=history(position,seed,0),b=history(position,seed,2),ea=marketEvidence(a),eb=marketEvidence(b);
  if(Math.abs(ea.bonus-eb.bonus)<.1){totals.excludedByHistoricalInput++;continue;}
  const[high,low]=ea.bonus>eb.bonus?[a,b]:[b,a];
  for(const field of ['skills','proficiency','reputation','trust','confidence','pressure','condition','fatigue','happiness','mentalStress','rival','fanMemory','projectStrain','clubProject'])low[field]=clone(high[field]);
  assert(validGame(high)&&validGame(low));assert.equal(overall(high),overall(low));
  const e=marketEvidence(high),l=marketEvidence(low);assert.equal(e.baseScore,l.baseScore);assert(e.bonus>l.bonus);assert(e.score>l.score);
  const minutes=high.playedMatches.filter(m=>m.season===high.season&&m.minutes>=35).reduce((n,m)=>n+m.minutes,0);assert.equal(e.qualifiedMinutes,minutes);assert.equal(e.confidence,Math.min(1,minutes/900));
  const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));assert.equal(e.bonus,e.confidence*clamp(8*(e.adjustedRating-6.8)+4*(e.goodRate-.4)+2*clamp(e.roleRatio-1,0,1)+3*clamp(e.gaPer90-.3,0,1),0,12));assert(e.bonus>=0&&e.bonus<=12);
  assert.equal(e.gaPer90,(e.goals+e.assists)*90/minutes);assert(e.roleExpected>0);
  const future=clone(high);future.objective.target.output=999;future.objective.target.minutes=1;assert.deepEqual(marketEvidence(future),e,'unplayed future objective changes recruitment evidence');
  pairs.push({position,seed,overall:overall(high),highBonus:e.bonus,ordinaryBonus:l.bonus});
  for(let draw=1;draw<=8;draw++){
   const x=clone(high),y=clone(low);x.rng=y.rng=(Math.imul(draw,2654435761)+seed*17)>>>0;
   for(const g of [x,y]){assert(choose(g,g.event.choices[0].id));assert.equal(g.event.kind,'INTEREST');assert(validGame(g));assert(g.market.length<=2);}
   const ex=marketEvidence(x),ey=marketEvidence(y);totals.pairs++;totals.postBonusHigher+=+(ex.bonus>ey.bonus);totals.bonusSum+=ex.bonus;totals.ordinaryBonusSum+=ey.bonus;totals.postOverallDifferenceSum+=Math.abs(overall(x)-overall(y));totals.contacts+=x.market.length;totals.ordinaryContacts+=y.market.length;totals.strongContacts+=x.market.filter(id=>byId(id).level>club(x).level).length;totals.ordinaryStrongContacts+=y.market.filter(id=>byId(id).level>club(y).level).length;totals.silent+=+!x.market.length;totals.ordinarySilent+=+!y.market.length;
  }
 }
 assert(pairs.length>=64);assert(totals.strongContacts>totals.ordinaryStrongContacts);assert(totals.bonusSum>totals.ordinaryBonusSum);assert(totals.silent>0&&totals.ordinarySilent>0);metrics.productionMarket={selection:'historical bonus difference >=0.1 before future window; equal current skills and material opportunity inputs; 8 RNG per pair',...totals,historicalPairs:pairs};
 const keeper=planFromOffer(publicOffers.GK),ke=marketEvidence(keeper);assert.equal(ke.gaPer90,0);
});
const afterHash=hash(moduleURL);assert.equal(afterHash,beforeHash,'source changed during promises tests');const report={engineSha256:beforeHash,groups,metrics};if(process.env.REPORT_FILE)fs.writeFileSync(process.env.REPORT_FILE,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({groups:groups.length,passed:groups.filter(g=>g.pass).length,metrics},null,2));if(groups.some(g=>!g.pass))process.exitCode=1;
